def compute_bureau_active_credit_count(app_train, bureau, bureau_bal, prev_app, install, cc_bal, pos_cash):
    bureau['is_active'] = (bureau['CREDIT_ACTIVE'] == 'Active').astype(int)
    agg = bureau.groupby('SK_ID_CURR').agg(val=('is_active', 'sum')).reset_index()
    result = app_train[['SK_ID_CURR']].merge(agg, on='SK_ID_CURR', how='left')
    result['val'] = result['val'].fillna(0)
    return result.set_index('SK_ID_CURR')['val'].rename('bureau_active_credit_count')

