def compute_prev_rejected_amt_ratio(app_train, bureau, bureau_bal, prev_app, install, cc_bal, pos_cash):
    prev_app['is_rejected'] = (prev_app['NAME_CONTRACT_STATUS'] == 'Refused').astype(int)
    agg = prev_app.groupby('SK_ID_CURR').agg(
        rejected_count=('is_rejected', 'sum'),
        total_count=('SK_ID_PREV', 'count')
    ).reset_index()
    agg['prev_rejected_amt_ratio'] = agg['rejected_count'] / (agg['total_count'] + 1)
    result = app_train[['SK_ID_CURR']].merge(agg[['SK_ID_CURR', 'prev_rejected_amt_ratio']], on='SK_ID_CURR', how='left')
    result['prev_rejected_amt_ratio'] = result['prev_rejected_amt_ratio'].fillna(0)
    return result.set_index('SK_ID_CURR')['prev_rejected_amt_ratio'].rename('prev_rejected_amt_ratio')

